<script lang="ts">
    import {onMount, tick, createEventDispatcher} from 'svelte'
    import {Plus, Image as ImageIcon, FileText, Layers, Checkbox, Link2, Trash, ZoomIn, ZoomOut, Size, Cross2, DragHandleDots2, Target, LightningBolt, Download, Reset} from 'radix-icons-svelte'
    import {makeId} from '@/lib/center'
    import {readImage} from '@/lib/richNotes'
    import {mapNode, mapBounds, nodeHeight, nodeWidth, validateMindMap, readMapFile, type MindMap, type MapKind, type MapFile} from '@/lib/mindMap'
    export let value:MindMap
    export let mobile=false
    export let disabled=false
    export let dirty=false
    export let saveError=''
    let expanded=false
    const dispatch=createEventDispatcher()
    let board:HTMLDivElement, imagePicker:HTMLInputElement, filePicker:HTMLInputElement
    let selectedId=value.nodes[0]?.id||'', inspector=false, connect=false, error='', busy=false, pendingNode=''
    let zoom=1, panX=0, panY=0, history:MindMap[]=[], future:MindMap[]=[]
    let drag:{id:string;x:number;y:number;startX:number;startY:number;moved:boolean}|null=null
    let resizing:{id:string;x:number;y:number;width:number;height:number}|null=null
    let moved=false, pinch:{distance:number;zoom:number;x:number;y:number;worldX:number;worldY:number}|null=null
    const pointers=new Map<number,{x:number;y:number}>()
    const kinds:{id:MapKind;title:string;icon:any}[]=[{id:'idea',title:'Идея',icon:LightningBolt},{id:'goal',title:'Цель',icon:Target},{id:'plan',title:'План',icon:Checkbox},{id:'images',title:'Фото',icon:ImageIcon},{id:'note',title:'Заметка',icon:FileText}]
    $: selected=value.nodes.find(node=>node.id===selectedId)
    $: bounds=mapBounds(value)
    $: links=value.edges.map(edge=>({...edge,fromNode:value.nodes.find(n=>n.id===edge.from)!,toNode:value.nodes.find(n=>n.id===edge.to)!})).filter(e=>e.fromNode&&e.toNode)
    function checkpoint(){history=[...history.slice(-14),structuredClone(value)];future=[]}
    function changed(){value={...value,nodes:[...value.nodes],edges:[...value.edges]};dispatch('change')}
    function edit(){changed()}
    function undo(){if(!history.length||busy)return;future=[...future,structuredClone(value)];value=history[history.length-1];history=history.slice(0,-1);selectedId=value.nodes[0].id;changed()}
    function redo(){if(!future.length||busy)return;history=[...history,structuredClone(value)];value=future[future.length-1];future=future.slice(0,-1);selectedId=value.nodes[0].id;changed()}
    function focusNode(id:string){const n=value.nodes.find(n=>n.id===id);if(!n||!board)return;selectedId=id;zoom=mobile ? .95 : 1;panX=(board.clientWidth-nodeWidth(n)*zoom)/2-n.x*zoom;panY=(board.clientHeight-nodeHeight(n)*zoom)/2-n.y*zoom}
    async function expand(){expanded=!expanded;await tick();focusNode(selectedId)}
    function fit(){if(!board)return;const b=mapBounds(value);zoom=Math.max(.18,Math.min(1,(board.clientWidth-60)/b.width,(board.clientHeight-70)/b.height));panX=(board.clientWidth-b.width*zoom)/2-b.x*zoom;panY=(board.clientHeight-b.height*zoom)/2-b.y*zoom}
    function scale(next:number,x=board.clientWidth/2,y=board.clientHeight/2){next=Math.max(.18,Math.min(2,next));panX=x-(x-panX)/zoom*next;panY=y-(y-panY)/zoom*next;zoom=next}
    function wheel(e:WheelEvent){e.preventDefault();const r=board.getBoundingClientRect();if(e.ctrlKey||e.metaKey)scale(zoom*Math.exp(-e.deltaY*.004),e.clientX-r.left,e.clientY-r.top);else{panX-=e.deltaX;panY-=e.deltaY}}
    function boardStart(e:PointerEvent){if(!(e.target as HTMLElement).closest('.map-node'))start(e)}
    function start(e:PointerEvent,id=''){
        if(disabled||e.button!==0||busy)return
        const target=e.target as HTMLElement
        if(target.closest('input,textarea,select,.inspector,.map-controls,.minimap,.resize-node'))return
        pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});board.setPointerCapture(e.pointerId)
        if(pointers.size===2){const [a,b]=[...pointers.values()],r=board.getBoundingClientRect(),x=(a.x+b.x)/2-r.left,y=(a.y+b.y)/2-r.top;pinch={distance:Math.hypot(a.x-b.x,a.y-b.y),zoom,x,y,worldX:(x-panX)/zoom,worldY:(y-panY)/zoom};drag=null;return}
        if(id){selectedId=id;const n=value.nodes.find(n=>n.id===id)!;checkpoint();drag={id,x:n.x,y:n.y,startX:e.clientX,startY:e.clientY,moved:false}}
        else drag={id:'',x:panX,y:panY,startX:e.clientX,startY:e.clientY,moved:false}
        moved=false
    }
    function resizeStart(e:PointerEvent,id:string){if(disabled||busy||e.button!==0)return;e.preventDefault();e.stopPropagation();const n=value.nodes.find(n=>n.id===id)!;checkpoint();selectedId=id;resizing={id,x:e.clientX,y:e.clientY,width:nodeWidth(n),height:nodeHeight(n)};board.setPointerCapture(e.pointerId)}
    function move(e:PointerEvent){
        if(resizing){const n=value.nodes.find(n=>n.id===resizing!.id);if(n){n.width=Math.round(Math.max(240,Math.min(1000,resizing.width+(e.clientX-resizing.x)/zoom)));n.height=Math.round(Math.max(160,Math.min(1400,resizing.height+(e.clientY-resizing.y)/zoom)));changed()}return}
        if(!pointers.has(e.pointerId))return
        pointers.set(e.pointerId,{x:e.clientX,y:e.clientY})
        if(pinch&&pointers.size===2){const [a,b]=[...pointers.values()],r=board.getBoundingClientRect();zoom=Math.max(.18,Math.min(2,pinch.zoom*Math.hypot(a.x-b.x,a.y-b.y)/Math.max(1,pinch.distance)));panX=(a.x+b.x)/2-r.left-pinch.worldX*zoom;panY=(a.y+b.y)/2-r.top-pinch.worldY*zoom;moved=true;return}
        if(!drag)return
        const dx=e.clientX-drag.startX,dy=e.clientY-drag.startY
        if(Math.abs(dx)+Math.abs(dy)>5)drag.moved=moved=true
        if(drag.id){const node=value.nodes.find(n=>n.id===drag!.id)!;node.x=Math.round(Math.max(-9500,Math.min(9500,drag.x+dx/zoom)));node.y=Math.round(Math.max(-9500,Math.min(9500,drag.y+dy/zoom)));if(drag.moved)changed()}
        else {panX=drag.x+dx;panY=drag.y+dy}
    }
    function end(e:PointerEvent){if(resizing){resizing=null;if(board.hasPointerCapture(e.pointerId))board.releasePointerCapture(e.pointerId);return;}if(drag?.id&&!drag.moved&&e.type!=='pointercancel'){history=history.slice(0,-1);choose(drag.id)}pointers.delete(e.pointerId);if(board.hasPointerCapture(e.pointerId))board.releasePointerCapture(e.pointerId);if(!pointers.size){drag=null;pinch=null}}
    function choose(id:string){if(moved){moved=false;return}if(connect&&selectedId&&selectedId!==id){if(value.edges.some(e=>e.from===selectedId&&e.to===id||e.to===selectedId&&e.from===id)){error='Эти карточки уже связаны.';return}if(value.edges.length>=160){error='В одной карте — до 160 связей.';return}checkpoint();value.edges=[...value.edges,{id:makeId(),from:selectedId,to:id}];connect=false;changed()}else {selectedId=id;inspector=true}}
    async function add(kind:MapKind){if(value.nodes.length>=80||value.edges.length>=160){error='В одной карте — до 80 карточек и 160 связей.';return}checkpoint();const parent=selected||value.nodes[0],count=value.edges.filter(e=>e.from===parent.id).length;const n=mapNode(kind,kinds.find(k=>k.id===kind)!.title,Math.min(9500,parent.x+400),Math.min(9500,parent.y+(count%4)*240));for(let attempt=0;attempt<80&&value.nodes.some(other=>n.x<other.x+nodeWidth(other)+40&&n.x+nodeWidth(n)+40>other.x&&n.y<other.y+nodeHeight(other)+40&&n.y+nodeHeight(n)+40>other.y);attempt++){n.y=Math.min(9400,parent.y+Math.floor(attempt/3)*270);n.x=Math.min(9400,parent.x+400+(attempt%3)*380)}if(kind==='plan')n.items=[{id:makeId(),text:'Первый шаг',done:false}];value.nodes=[...value.nodes,n];value.edges=[...value.edges,{id:makeId(),from:parent.id,to:n.id}];selectedId=n.id;inspector=true;changed();await tick();panX=board.clientWidth*.35-(n.x+150)*zoom;panY=board.clientHeight*.4-(n.y+80)*zoom}
    function remove(){if(!selected)return;if(value.nodes.length===1){error='В карте должна остаться хотя бы одна карточка.';return}if(!confirm(`Удалить карточку «${selected.title}» вместе с её вложениями и связями?`))return;checkpoint();value.nodes=value.nodes.filter(n=>n.id!==selectedId);value.edges=value.edges.filter(e=>e.from!==selectedId&&e.to!==selectedId);selectedId=value.nodes[0].id;inspector=false;changed()}
    function removeLink(id:string){checkpoint();value.edges=value.edges.filter(e=>e.id!==id);changed()}
    function toggleItem(nodeId:string,itemId:string){checkpoint();const item=value.nodes.find(n=>n.id===nodeId)?.items.find(i=>i.id===itemId);if(item)item.done=!item.done;changed()}
    function addItem(){if(!selected||selected.items.length>=100)return;checkpoint();selected.items=[...selected.items,{id:makeId(),text:'',done:false}];changed()}
    function image(){if(!selected)return;pendingNode=selected.id;if(mobile&&(window as any).NativeCenter?.pickImage){busy=true;(window as any).NativeCenter.pickImage()}else imagePicker.click()}
    async function insertImage(src:string,name:string){const node=value.nodes.find(n=>n.id===pendingNode);if(!node)return;if(node.images.length>=8)throw new Error('В карточке — до 8 изображений.');const next=structuredClone(value);next.nodes.find(n=>n.id===node.id)!.images.push({id:makeId(),src,name:name.slice(0,160)});validateMindMap(next);checkpoint();value=next;changed()}
    async function filesPicked(files:File[],images:boolean){if(!files.length)return;busy=true;error='';try{for(const file of files){if(images)await insertImage(await readImage(file,600_000),file.name);else await insertFile(await readMapFile(file))}}catch(e){error=String(e)}finally{busy=false}}
    function attach(){if(!selected)return;pendingNode=selected.id;if(mobile&&(window as any).NativeCenter?.pickAttachment){busy=true;(window as any).NativeCenter.pickAttachment()}else filePicker.click()}
    async function insertFile(file:MapFile){const next=structuredClone(value),node=next.nodes.find(n=>n.id===pendingNode);if(!node)return;if(node.files.length>=8)throw new Error('В карточке — до 8 файлов.');node.files.push(file);validateMindMap(next);checkpoint();value=next;changed()}
    async function download(file:MapFile){try{if(mobile&&(window as any).NativeCenter?.exportAttachment){(window as any).NativeCenter.exportAttachment(JSON.stringify(file));return}const bytes=Uint8Array.from(atob(file.data),c=>c.charCodeAt(0));if((window as any).__TAURI_INTERNALS__){const {save}=await import('@tauri-apps/plugin-dialog'),{writeFile}=await import('@tauri-apps/plugin-fs');const path=await save({defaultPath:file.name,filters:[{name:'Вложение карты',extensions:[file.name.split('.').pop()||'txt']}]});if(path)await writeFile(path,bytes);return}const url=URL.createObjectURL(new Blob([bytes],{type:file.mime})),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error='Не удалось сохранить файл: '+String(e)}}
    function path(a:MindMap['nodes'][number],b:MindMap['nodes'][number]){const right=b.x>=a.x,ax=a.x+(right?nodeWidth(a):0),bx=b.x+(right?0:nodeWidth(b)),ay=a.y+55,by=b.y+55,curve=Math.max(80,Math.abs(bx-ax)*.5);return `M${ax},${ay} C${ax+(right?curve:-curve)},${ay} ${bx+(right?-curve:curve)},${by} ${bx},${by}`}
    function keyMove(e:KeyboardEvent,id:string){if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();checkpoint();const n=value.nodes.find(n=>n.id===id)!;const amount=e.shiftKey?50:10;n.x=Math.max(-9500,Math.min(9500,n.x+(e.key==='ArrowRight'?amount:e.key==='ArrowLeft'?-amount:0)));n.y=Math.max(-9500,Math.min(9500,n.y+(e.key==='ArrowDown'?amount:e.key==='ArrowUp'?-amount:0)));changed()}
    onMount(()=>{tick().then(()=>mobile?focusNode(selectedId):fit());const observer=new ResizeObserver(()=>{if(board.clientWidth<300)inspector=false});observer.observe(board);const nativeImage=async(e:Event)=>{if(!busy)return;const r=(e as CustomEvent).detail;try{if(r.error)throw new Error(r.error);if(r.src)await insertImage(r.src,'Изображение')}catch(e){error=String(e)}finally{busy=false}};const nativeFile=async(e:Event)=>{if(!busy)return;const r=(e as CustomEvent).detail;try{if(r.error)throw new Error(r.error);if(r.file)await insertFile({...r.file,id:makeId()})}catch(e){error=String(e)}finally{busy=false}};window.addEventListener('jarvis-image',nativeImage);window.addEventListener('jarvis-attachment',nativeFile);return()=>{observer.disconnect();window.removeEventListener('jarvis-image',nativeImage);window.removeEventListener('jarvis-attachment',nativeFile)}})
</script>

<section class="mind-map" class:expanded class:mobile aria-label="Редактор карты мыслей">
    <div class="map-toolbar" role="toolbar" aria-label="Добавление карточек">
        <div class="map-brand"><Layers width={20} height={20}/><span>КАРТА МЫСЛЕЙ</span><small>{value.nodes.length} карточек</small></div>
        <div class="map-top-actions"><button type="button" aria-label={expanded?'Свернуть карту':'Развернуть карту'} on:click={expand}><Size width={17} height={17}/>{expanded?'Свернуть':'Развернуть'}</button><button type="button" class="save-map" disabled={disabled||busy} on:click={()=>dispatch('save')}>{dirty?'Сохранить карту':'Сохранено'}</button></div>
        <div class="add-types">{#each kinds as kind}<button type="button" disabled={disabled||busy} on:click={()=>add(kind.id)}><svelte:component this={kind.icon} width={17} height={17}/>{kind.title}</button>{/each}</div>
    </div>
    {#if mobile}<label class="map-jump">Перейти к карточке<select aria-label="Перейти к карточке" value={selectedId} on:change={e=>{focusNode(e.currentTarget.value);inspector=false}}>{#each value.nodes as node}<option value={node.id}>{node.title||'Без названия'}</option>{/each}</select></label>{/if}
    <div class="map-board" bind:this={board} role="group" aria-label="Поле карты мыслей" on:wheel|nonpassive={wheel} on:pointerdown={boardStart} on:pointermove={move} on:pointerup={end} on:pointercancel={end}>
        <div class="map-world" style:transform={`translate(${panX}px,${panY}px) scale(${zoom})`}>
            <svg class="connections" aria-hidden="true" width="1" height="1">{#each links as edge}<path d={path(edge.fromNode,edge.toNode)}/><circle cx={edge.fromNode.x+(edge.toNode.x>=edge.fromNode.x?nodeWidth(edge.fromNode):0)} cy={edge.fromNode.y+55} r="4"/><circle cx={edge.toNode.x+(edge.toNode.x>=edge.fromNode.x?0:nodeWidth(edge.toNode))} cy={edge.toNode.y+55} r="4"/>{/each}</svg>
            {#each value.nodes as node (node.id)}
                <article class="map-node" class:chosen={selectedId===node.id} class:root-node={node.id===value.nodes[0].id} class:sized={!!node.height} style:width={`${nodeWidth(node)}px`} style:height={node.height?`${node.height}px`:undefined} style:left={`${node.x}px`} style:top={`${node.y}px`} data-node-id={node.id}>
                    <button type="button" class="node-heading" aria-label={`Карточка: ${node.title}`} disabled={disabled} on:pointerdown|stopPropagation={e=>{if(!connect)start(e,node.id)}} on:click={()=>choose(node.id)} on:keydown={e=>keyMove(e,node.id)}><span class="node-icon"><svelte:component this={node.id===value.nodes[0].id?Layers:kinds.find(k=>k.id===node.kind)?.icon||Layers} width={23} height={23}/></span><strong>{node.title||'Без названия'}</strong><DragHandleDots2 width={17} height={17}/></button>
                    {#if node.text}<p class="node-text">{node.text}</p>{/if}
                    {#if node.images.length}<div class="node-images" style:height={`${node.imageHeight??(node.height?Math.max(80,node.height-125):110)}px`}>{#each node.images.slice(0,2) as image}<img src={image.src} alt={image.name} style:object-fit={node.imageFit??'contain'} draggable="false"/>{/each}{#if node.images.length>2}<span>+{node.images.length-2}</span>{/if}</div>{:else if node.kind==='images'}<button class="image-empty" type="button" disabled={disabled||busy} on:click={()=>{selectedId=node.id;image()}}><ImageIcon width={25} height={25}/>Добавить изображение</button>{/if}
                    {#if node.items.length}<div class="node-plan"><div class="plan-progress"><span>{node.items.filter(i=>i.done).length}/{node.items.length}</span><progress value={node.items.filter(i=>i.done).length} max={node.items.length}></progress></div>{#each node.items.slice(0,4) as item}<label class:finished={item.done}><input type="checkbox" checked={item.done} aria-label={`Шаг: ${item.text}`} disabled={disabled} on:change={()=>toggleItem(node.id,item.id)}/><span>{item.text||'Новый шаг'}</span></label>{/each}{#if node.items.length>4}<small>Ещё {node.items.length-4} · откройте карточку</small>{/if}</div>{/if}
                    {#if node.files.length}<button class="node-file" type="button" on:click={()=>download(node.files[0])}><FileText width={18} height={18}/><span>{node.files[0].name}</span><Download width={16} height={16}/></button>{/if}
                    {#if !node.text&&!node.items.length&&!node.images.length&&!node.files.length&&node.kind!=='images'}<p class="node-placeholder">Откройте карточку, чтобы добавить мысли</p>{/if}
                    <button type="button" class="resize-node" aria-label={`Изменить размер карточки ${node.title}`} title="Потяните для изменения размера" disabled={disabled||busy} on:pointerdown={e=>resizeStart(e,node.id)} on:click|stopPropagation={()=>{selectedId=node.id;inspector=true}}>◢</button>
                </article>
            {/each}
        </div>
        {#if connect}<div class="connect-notice" role="status">Нажмите другую карточку для связи<button type="button" aria-label="Отменить связь" on:click={()=>connect=false}><Cross2/></button></div>{/if}
        {#if inspector&&selected}
            <aside class="inspector" aria-label="Содержимое карточки" on:pointerdown|stopPropagation on:wheel|stopPropagation>
                <div class="inspector-heading"><strong>Карточка</strong><button type="button" aria-label="Закрыть карточку" on:click={()=>inspector=false}><Cross2 width={20} height={20}/></button></div>
                <label>Название<input aria-label="Название карточки" maxlength="120" bind:value={selected.title} disabled={disabled} on:focus={checkpoint} on:input={edit}/></label>
                <label>Текст<textarea aria-label="Текст карточки" maxlength="4000" rows="3" bind:value={selected.text} disabled={disabled} on:focus={checkpoint} on:input={edit} placeholder="Мысли, детали или ссылки…"></textarea></label>
                <div class="inspector-actions"><button type="button" disabled={disabled||busy} on:click={image}><ImageIcon/>Картинка</button><button type="button" disabled={disabled||busy} on:click={attach}><FileText/>Файл</button><button type="button" disabled={disabled} on:click={addItem}><Checkbox/>Шаг плана</button></div>
                <small class="attachment-hint">Файлы: PDF, Word или текст до 700 КБ.</small>
                <details><summary>Размер и оформление</summary>
                    <label>Ширина карточки<input aria-label="Ширина карточки" type="range" min="240" max="1000" step="10" value={nodeWidth(selected)} on:focus={checkpoint} on:input={e=>{selected.width=Number(e.currentTarget.value);changed()}}/></label>
                    <label>Высота карточки<input aria-label="Высота карточки" type="range" min="160" max="1400" step="10" value={nodeHeight(selected)} on:focus={checkpoint} on:input={e=>{selected.height=Number(e.currentTarget.value);changed()}}/></label>
                    <label>Высота фотографий<input aria-label="Высота фотографий" type="range" min="80" max="800" step="10" value={selected.imageHeight??110} on:focus={checkpoint} on:input={e=>{selected.imageHeight=Number(e.currentTarget.value);changed()}}/></label>
                    <label>Фотографии<select aria-label="Отображение фотографий" value={selected.imageFit??'contain'} on:change={e=>{checkpoint();selected.imageFit=e.currentTarget.value==='cover'?'cover':'contain';changed()}}><option value="contain">Целиком</option><option value="cover">Заполнить с обрезкой</option></select></label>
                    <button type="button" on:click={()=>{checkpoint();delete selected.width;delete selected.height;delete selected.imageHeight;changed()}}>Автоматический размер</button>
                </details>
                {#if selected.images.length}<div class="image-list">{#each selected.images as image}<div><img src={image.src} alt={image.name}/><button type="button" aria-label={`Удалить изображение ${image.name}`} disabled={disabled} on:click={()=>{checkpoint();selected.images=selected.images.filter(i=>i.id!==image.id);changed()}}><Cross2/></button></div>{/each}</div>{/if}
                {#each selected.items as item,index (item.id)}<div class="map-plan-row"><input type="checkbox" aria-label={`Выполнить шаг ${index+1}`} checked={item.done} disabled={disabled} on:change={()=>toggleItem(selected.id,item.id)}/><input aria-label={`Шаг плана ${index+1}`} maxlength="1000" bind:value={item.text} disabled={disabled} on:focus={checkpoint} on:input={edit}/><button type="button" aria-label={`Удалить шаг ${index+1}`} disabled={disabled} on:click={()=>{checkpoint();selected.items=selected.items.filter(i=>i.id!==item.id);changed()}}><Cross2/></button></div>{/each}
                {#each selected.files as file}<div class="attachment-row"><button type="button" on:click={()=>download(file)}><FileText/><span>{file.name}<small>{Math.ceil(file.size/1024)} КБ · сохранить</small></span><Download/></button><button type="button" aria-label={`Удалить файл ${file.name}`} disabled={disabled} on:click={()=>{checkpoint();selected.files=selected.files.filter(f=>f.id!==file.id);changed()}}><Cross2/></button></div>{/each}
                <div class="inspector-bottom"><button type="button" disabled={disabled} on:click={()=>{connect=true;inspector=false}}><Link2/>Связать</button><button class="danger" type="button" disabled={disabled||value.nodes.length===1} on:click={remove}><Trash/>Удалить</button></div>
                {#if links.some(e=>e.from===selectedId||e.to===selectedId)}<details><summary>Связи карточки</summary>{#each links.filter(e=>e.from===selectedId||e.to===selectedId) as edge}<div class="link-row"><span>{edge.from===selectedId?edge.toNode.title:edge.fromNode.title}</span><button type="button" disabled={disabled} aria-label={`Убрать связь ${edge.id}`} on:click={()=>removeLink(edge.id)}><Cross2/></button></div>{/each}</details>{/if}
            </aside>
        {/if}
        <div class="map-controls" role="toolbar" aria-label="Управление картой"><button type="button" title="Отменить изменение" aria-label="Отменить изменение карты" disabled={!history.length||disabled} on:click={undo}><Reset width={18} height={18}/></button><button type="button" aria-label="Повторить изменение карты" disabled={!future.length||disabled} on:click={redo}><Reset width={18} height={18} style="transform:scaleX(-1)"/></button><span class="separator"></span><button type="button" class:active={connect} aria-pressed={connect} aria-label="Связать карточки" disabled={disabled} on:click={()=>{connect=!connect;inspector=false}}><Link2 width={18} height={18}/></button><button type="button" aria-label="Уменьшить карту" on:click={()=>scale(zoom/1.2)}><ZoomOut width={18} height={18}/></button><span class="zoom-value">{Math.round(zoom*100)}%</span><button type="button" aria-label="Увеличить карту" on:click={()=>scale(zoom*1.2)}><ZoomIn width={18} height={18}/></button><button type="button" aria-label="Показать всю карту" on:click={fit}><Size width={18} height={18}/></button></div>
        <button type="button" class="minimap" aria-label="Обзор всей карты" on:click={fit}><svg viewBox={`${bounds.x-40} ${bounds.y-40} ${bounds.width+80} ${bounds.height+80}`} aria-hidden="true">{#each links as edge}<path d={path(edge.fromNode,edge.toNode)}/>{/each}{#each value.nodes as node}<rect x={node.x} y={node.y} width={nodeWidth(node)} height={nodeHeight(node)} rx="15" class:selected={selectedId===node.id}/>{/each}</svg></button>
        {#if busy}<div class="map-busy" role="status"><span></span>Добавляю вложение…</div>{/if}
    </div>
    <div class="map-hint"><span>{mobile?'Двигайте поле пальцем · масштаб — двумя пальцами или кнопками':'Перетаскивайте карточки за заголовок · Ctrl + колесо — масштаб'}</span><span>Изменения сохраняются вместе с заметкой</span></div>
    {#if error||saveError}<p class="map-error" role="alert">{error||saveError}<button type="button" aria-label="Закрыть сообщение" on:click={()=>{error='';dispatch('clearError')}}><Cross2/></button></p>{/if}
    <input type="file" class="hidden-picker" bind:this={imagePicker} accept="image/png,image/jpeg,image/webp,image/gif,image/bmp" multiple on:change={e=>{void filesPicked(Array.from(e.currentTarget.files||[]),true);e.currentTarget.value=''}}/>
    <input type="file" class="hidden-picker" bind:this={filePicker} accept=".pdf,.txt,.md,.docx" multiple on:change={e=>{void filesPicked(Array.from(e.currentTarget.files||[]),false);e.currentTarget.value=''}}/>
</section>

